import re,os,glob
def slug(h):
    h=h.lower().strip(); h=re.sub(r'[^\w\s-]','',h); return h.replace(' ','-')
files=['AGENTS.md','custom.md']+sorted(glob.glob('agent-data/*.md'))
anchors={f:set(slug(m.group(1)) for m in re.finditer(r'^#+\s+(.*)$',open(f).read(),re.M)) for f in files}
for f in files:
    txt=open(f).read(); d=os.path.dirname(f)
    for m in re.finditer(r'\]\(([^)\s]+)\)|^\[[^\]]+\]:\s*(\S+)',txt,re.M):
        t=m.group(1) or m.group(2)
        if t.startswith('http') or '<' in t: continue
        path,_,frag=t.partition('#')
        tgt=os.path.normpath(os.path.join(d,path)) if path else f
        if tgt not in anchors:
            if not os.path.exists(tgt): print('MISSING',f,t)
            continue
        if frag and frag not in anchors[tgt]: print('BAD',f,t)
print('anchors checked')
EOF
